 req:=e10.normalize_market_screener_request(o,'catalog','variant','count','completed_sale','2026-01-01','2026-02-01','2026-02-01','USD','none',null,null,'{}','cohort_asc',50);select count(*),(array_agg(row_data))[1]into n,j from e10.market_screener_rows(o,req);if n is distinct from 1 or(j->>'catalog_entity_count')::integer is distinct from 1 or(j->>'owned_copy_count')::integer is distinct from 2 or(j->>'observed_count')::integer is distinct from 3 or(j->>'linked_duplicate_count')::integer is distinct from 2 then raise exception'independent 1/2/3 counts or duplicate total failed: %',j;end if;
