 req:=e10.normalize_market_screener_request(o,'catalog','variant_condition','transaction_total','completed_sale','2026-01-01','2026-02-01','2026-02-01','USD','none',null,null,'{"condition_state":"raw"}','mean_desc',50);select count(*),(array_agg(row_data))[1]into n,j from e10.market_screener_rows(o,req);if n is distinct from 1 or(j->>'mean_transaction_total')::numeric is distinct from 100 or(j->>'median_transaction_total')::numeric is distinct from 100 or(j->>'latest_transaction_total')::numeric is distinct from 110 then raise exception'transaction-total aggregate contract failed: %',j;end if;
