 req:=e10.normalize_market_screener_request(o,'catalog','variant','count','asking_price','2026-01-01','2026-02-01','2026-02-01','USD','none',null,null,'{"graded":false}','cohort_asc',50);select count(*)into n from e10.market_screener_rows(o,req);if n is distinct from 0 then raise exception'unknown grade misclassified raw';end if;
