 req:=e10.normalize_market_screener_request(o,'catalog','release','count','completed_sale','2026-01-01','2026-02-01','2026-02-01',null,'none',null,null,'{}','cohort_asc',50);select row_data into j from e10.market_screener_rows(o,req);if(j->>'catalog_entity_count')::integer is distinct from 2 then raise exception'release grouping count failed';end if;
